using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed partial class FlightMeasurementPlayMode {
 [Serializable]public class R11Row {public string id,kind,launch,final,target,fixture;public bool pauseStable,resetClean;public List<BreakRecord> breaks=new List<BreakRecord>();public List<string> frames=new List<string>();}
 [Serializable]public class R11Report {public string state="RUNNING",revision="route-r11-blockout1",limits="Static layout captures and deliberately positioned segment fixtures do not prove ordinary launch reach. Same version repeats and old/new deltas are separate. No C7/adoption verdict.";public List<R11Row> rows=new List<R11Row>();}
 void StartRouteChargeR11(float angle,int level=0,float rate=2,int direction=1){Call(current,"Configure",JsonUtility.ToJson(new InputSpec{angle=angle,power=100,direction=direction,upgradeLevel=level}));var aim=JsonUtility.ToJson(new Aim{angle=angle,power=100,direction=direction});var work=JsonUtility.ToJson(new Work{direction=direction,distance=rate/60,seconds=1f/60});Call(current,"BeginAim","");Call(current,"PreviewLaunch",aim);Call(current,"BeginSpinCharge","");for(int i=0;i<601;i++){Call(current,"AddSpinWork",work);Call(current,"Tick",1f/60);}Call(current,"ReleaseLaunch",aim);}
 void R11Breaks(R11Row row){var sim=Property(current,"ReviewSimulation");foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.breaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});}
 void CaptureSectorR11(string id,float x,float y,float size){var c=(Camera)Property(current,"ReviewCamera");var sim=Property(current,"ReviewSimulation")??Field(current,"world");using(var scope=new RenderIsolation(current.gameObject.scene,(UnityEngine.SceneManagement.Scene)Property(sim,"Scene"))){var p=c.transform.position;var q=c.transform.rotation;float sz=c.orthographicSize,asp=c.aspect;var output=Path.Combine(Evidence,"layout-only");Directory.CreateDirectory(output);foreach(var wh in new[]{new[]{844,390},new[]{390,844}}){c.transform.position=new Vector3(x,y,-35);c.transform.LookAt(new Vector3(x,y,0));c.orthographicSize=size;c.aspect=(float)wh[0]/wh[1];var rt=new RenderTexture(wh[0],wh[1],24);rt.Create();var prev=RenderTexture.active;c.targetTexture=rt;RenderTexture.active=rt;c.Render();var im=new Texture2D(wh[0],wh[1],TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,wh[0],wh[1]),0,0);im.Apply();File.WriteAllBytes(Path.Combine(output,id+"-"+wh[0]+".png"),im.EncodeToPNG());c.targetTexture=null;RenderTexture.active=prev;UnityEngine.Object.DestroyImmediate(im);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}c.transform.SetPositionAndRotation(p,q);c.orthographicSize=sz;c.aspect=asp;}}
 [UnityTest]public IEnumerator R11RouteBlockout(){Directory.CreateDirectory(Evidence);string path=Path.Combine(Evidence,"route-blockout.json");Assert.That(File.Exists(path),Is.False);var report=new R11Report();Action save=()=>File.WriteAllText(path,JsonUtility.ToJson(report,true));save();
 foreach(var spec in new[]{new RoofSpec{name="r10-standard",angle=12,power=100},new RoofSpec{name="r11-standard",angle=12,power=100},new RoofSpec{name="r10-fast35",angle=35,power=100,level=3},new RoofSpec{name="r11-fast35",angle=35,power=100,level=3},new RoofSpec{name="r11-high65",angle=65,power=100,level=3}}){bool route=spec.name.StartsWith("r11");yield return NewRetrySubject(false,true,true,true,true,route);StartRouteChargeR11(spec.angle,spec.level,spec.level==3?6:2);var row=new R11Row{id=spec.name,kind="normal-charge-launch",launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.rows.Add(row);save();int captured=0;var marks=new[]{30f,150,620,850,1000,1370,2110,2740};for(int t=0;t<8000&&!(bool)Property(current,"Finished");t++){Call(current,"Tick",1f/60);if(captured<marks.Length&&F(State(current),"distance")>marks[captured]){CaptureRoute(row.id,"x"+marks[captured]);row.frames.Add("x"+marks[captured]);captured++;}}
 row.final=JsonUtility.ToJson(State(current));R11Breaks(row);CaptureRoute(row.id,"result");save();Assert.That((bool)Property(current,"Finished"),Is.True,row.id);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty,row.id);
 if(row.id=="r11-standard"){
 var recipe=JsonUtility.FromJson<R11RecipeRead>(Resources.Load<TextAsset>("WorldRouteR11").text);foreach(var s in recipe.sectors)CaptureSectorR11(s.id,s.viewX,s.viewY,s.viewSize);
 Call(current,"SetPaused","1");float clock=F(State(current),"time");Call(current,"Tick",1f/60);row.pauseStable=F(State(current),"time")==clock;Call(current,"SetPaused","0");Call(current,"SetReducedMotion","1");Call(current,"RetryLaunch","");var retry=new R11Row{id="r11-standard-reduced-retry",kind="same-input-retry",launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.rows.Add(retry);for(int i=0;i<8000&&!(bool)Property(current,"Finished");i++)Call(current,"Tick",1f/60);retry.final=JsonUtility.ToJson(State(current));R11Breaks(retry);CaptureRoute(retry.id,"result");save();Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(State(current),"physicsFault"),Is.Empty);Call(current,"Prepare","");row.resetClean=F(State(current),"time")==0&&Convert.ToInt32(Field(State(current),"destructionEvent"))==0;Assert.That(row.pauseStable&&row.resetClean,Is.True);save();}
 Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 foreach(var spec in new[]{new[]{"country","r11-country-1-0-0-rail_glass_planter_display_r10"},new[]{"launchrange","r11-launchrange-1-0-0-port_lattice_loader_r10"},new[]{"orbit","r11-orbit-1-0-0-facade_break_panel"}}){yield return NewRetrySubject(false,true,true,true,true,true);StartRouteChargeR11(12,3,6);var sim=Property(current,"ReviewSimulation");var row=new R11Row{id="segment-"+spec[0],kind="deliberately-positioned-contact-fixture",target=spec[1],launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};row.fixture=(string)Call(sim,"ReviewRouteSegmentR11",spec[1]);report.rows.Add(row);save();bool broke=false;for(int t=0;t<120&&!broke;t++){Call(current,"Tick",1f/60);foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))if((string)Field(e,"id")==row.target)broke=true;}row.final=JsonUtility.ToJson(State(current));R11Breaks(row);CaptureRoute(row.id,"contact");save();Assert.That(broke,Is.True,row.id+" actual target did not break");Assert.That((string)Field(State(current),"physicsFault"),Is.Empty,row.id);Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED";save();}
 [UnityTest]public IEnumerator R11LayoutAndEnd(){yield return NewRetrySubject(false,true,true,true,true,true);StartRouteChargeR11(12);var recipe=JsonUtility.FromJson<R11RecipeRead>(Resources.Load<TextAsset>("WorldRouteR11").text);foreach(var sector in recipe.sectors)CaptureSectorR11(sector.id,sector.viewX,sector.viewY,sector.viewSize);var sim=Property(current,"ReviewSimulation");var body=(Rigidbody)Property(sim,"Body");body.position=new Vector3(3221,6,0);body.linearVelocity=Vector3.right*10;body.angularVelocity=Vector3.zero;UnityEngine.Physics.SyncTransforms();Call(current,"Tick",1f/60);var end=State(current);CaptureRoute("end-fixture","result");Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(end,"physicsFault"),Is.Empty);Call(current,"RetryLaunch","");var reset=State(current);Assert.That((bool)Property(current,"Finished"),Is.False);Assert.That(F(reset,"distance"),Is.EqualTo(0));Assert.That(Convert.ToInt32(Field(reset,"destructionEvent")),Is.EqualTo(0));Assert.That(F(reset,"worldLifeAge"),Is.EqualTo(0));CaptureRoute("end-fixture","retry");Directory.CreateDirectory(Evidence);File.WriteAllText(Path.Combine(Evidence,"layout-end.json"),"{\"method\":\"explicit terminal-position fixture, not natural reach\",\"end\":"+JsonUtility.ToJson(end)+",\"retry\":"+JsonUtility.ToJson(reset)+"}");Call(current,"ShutdownReviewPhysics");current=null;yield return null;}
 [Serializable]public class R11SectorRead {public string id;public float viewX,viewY,viewSize;}
